window.ZeeStore=(()=>{
 const KEY='zee-academy-lms-v6';
 const id=()=>crypto.randomUUID();
 const seed=()=>({version:1,courses:ZEE_COURSE_SEED.map(c=>({...c,published:true,archived:false,schedule:'Monday, Wednesday & Friday · 11:00 AM–12:30 PM',location:'Usha Niketan, 2nd Floor, House No. 122, Boring Patliputra Road, Patna',lessons:[
 {id:c.id+'-intro',module:'01 · Foundations',title:'Welcome to '+c.title,type:'video',duration:8,body:'Start with the fundamentals. In this sample lesson, you will explore the course goals, connect them to a practical brief, and plan your first project.\n\n1. Define the problem you want to solve.\n2. Identify your audience and their needs.\n3. Sketch a solution, collect feedback, and improve it.',url:'',published:true},
 {id:c.id+'-principles',module:'01 · Foundations',title:c.skills[0]+' — essential principles',type:'reading',duration:12,body:'A strong foundation makes every project easier.\n\nExplore '+c.skills.join(', ')+'. Start by observing three examples from everyday life. Note what works, what could improve, and how you would approach the same problem.\n\nPractice: create a one-page reference sheet with five key terms and your own examples.',url:'',published:true},
 {id:c.id+'-practice',module:'02 · Put it into practice',title:'From a brief to a first draft',type:'video',duration:18,body:'Break your brief into small steps: research, first draft, review, and iteration. Focus on the intention behind every decision. Save your process along the way; it is an important part of your portfolio.',url:'',published:true},
 {id:c.id+'-assignment',module:'02 · Put it into practice',title:'Your first creative brief',type:'assignment',duration:45,body:'Create a one-page brief for a local business or a room you would like to redesign. Include the objective, audience, three references, and a proposed approach.\n\nDeliverable: share a document link and a short explanation of your decisions.\n\nEvaluation: clarity (40%), relevance (30%), and reasoning (30%).',url:'',published:true},
 {id:c.id+'-project',module:'03 · Portfolio project',title:c.id==='marketing'?'Build a 7-day brand campaign':c.id==='interior'?'Design a compact living room':'Create your portfolio showcase',type:'project',duration:120,body:'Bring your learning together in a practical project.\n\n1. Choose a clear problem and write a short brief.\n2. Research three references.\n3. Develop your concept and document the process.\n4. Prepare a final presentation with your rationale.\n\nSubmit a portfolio or presentation link with a summary of your work. Feedback will appear here after admin review.',url:'',published:true}
 ]})),enrollments:[{id:'sample-marketing',courseId:'marketing',mode:'online',date:'2026-09-18',completed:['marketing-intro']},{id:'sample-interior',courseId:'interior',mode:'offline',date:'2026-09-18',completed:[]}],submissions:[]});
 function refreshCovers(data){
  for(const course of data.courses){
   const seedItem=ZEE_COURSE_SEED.find(c=>c.id===course.id);
   if(seedItem&&(!course.image||course.image.startsWith('courses/'))){
    course.image=seedItem.image;
   }
  }
  return data;
 }
 function read(){try{const v=JSON.parse(localStorage.getItem(KEY));if(v?.version===1&&Array.isArray(v.courses)&&Array.isArray(v.enrollments)&&Array.isArray(v.submissions))return refreshCovers(v)}catch{}return seed()}
 function save(data){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch{window.alert('Browser storage is full or unavailable. Your changes could not be saved.');return false}}
 function update(fn){const data=read();fn(data);return save(data)}
 function enroll(courseId,mode){return update(d=>{const old=d.enrollments.find(e=>e.courseId===courseId);if(old)old.mode=mode;else d.enrollments.push({id:id(),courseId,mode,date:new Date().toISOString().slice(0,10),completed:[]})})}
 return {read,save,update,enroll,id};
})();
